Page._content:
[
  {
    "hitokoto": "且将新火试新茶，诗酒趁年华。",
    "from": "苏轼《望江南》"
  },
  {
    "hitokoto": "人生如逆旅，我亦是行人。",
    "from": "苏轼《临江仙》"
  },
  {
    "hitokoto": "山川异域，风月同天。",
    "from": "长屋《绣袈裟衣缘》"
  },
  {
    "hitokoto": "星光不问赶路人，时光不负有心人。",
    "from": "大冰《我不》"
  },
  {
    "hitokoto": "生活明朗，万物可爱。",
    "from": "汪曾祺《人间草木》"
  },
  {
    "hitokoto": "醉后不知天在水，满船清梦压星河。",
    "from": "唐珙《题龙阳县青草湖》"
  },
  {
    "hitokoto": "人生若只如初见，何事秋风悲画扇。",
    "from": "纳兰性德《木兰花·拟古决绝词柬友》"
  },
  {
    "hitokoto": "愿我如星君如月，夜夜流光相皎洁。",
    "from": "范成大《车遥遥篇》"
  },
  {
    "hitokoto": "落霞与孤鹜齐飞，秋水共长天一色。",
    "from": "王勃《滕王阁序》"
  },
  {
    "hitokoto": "行到水穷处，坐看云起时。",
    "from": "王维《终南别业》"
  },
  {
    "hitokoto": "竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。",
    "from": "苏轼《定风波》"
  },
  {
    "hitokoto": "长风破浪会有时，直挂云帆济沧海。",
    "from": "李白《行路难·其一》"
  },
  {
    "hitokoto": "海内存知己，天涯若比邻。",
    "from": "王勃《送杜少府之任蜀州》"
  },
  {
    "hitokoto": "此去经年，应是良辰好景虚设。",
    "from": "柳永《雨霖铃·寒蝉凄切》"
  },
  {
    "hitokoto": "山有木兮木有枝，心悦君兮君不知。",
    "from": "《越人歌》"
  },
  {
    "hitokoto": "十年生死两茫茫，不思量，自难忘。",
    "from": "苏轼《江城子·乙卯正月二十日夜记梦》"
  },
  {
    "hitokoto": "众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。",
    "from": "辛弃疾《青玉案·元夕》"
  },
  {
    "hitokoto": "人生天地间，忽如远行客。",
    "from": "《古诗十九首》"
  },
  {
    "hitokoto": "保持热爱，奔赴山海。",
    "from": "网络"
  },
  {
    "hitokoto": "万物皆有裂痕，那是光照进来的地方。",
    "from": "莱昂纳德·科恩"
  },
  {
    "hitokoto": "世界上只有一种真正的英雄主义，那就是认清生活的真相后依然热爱生活。",
    "from": "罗曼·罗兰"
  },
  {
    "hitokoto": "满地都是六便士，他却抬头看见了月亮。",
    "from": "毛姆《月亮与六便士》"
  },
  {
    "hitokoto": "你要做一个不动声色的大人了。不准情绪化，不准偷偷想念，不准回头看。",
    "from": "村上春树《舞！舞！舞！》"
  },
  {
    "hitokoto": "我们在二十岁有共鸣的东西到了四十岁的时候不一定能产生共鸣，反之亦然。书本如此，生活亦如此。",
    "from": "加布瑞埃拉·泽文《岛上书店》"
  },
  {
    "hitokoto": "愿你一生努力，一生被爱，想要的都拥有，得不到的都释怀。",
    "from": "网络"
  },
  {
    "hitokoto": "热爱可抵岁月漫长。",
    "from": "网络"
  },
  {
    "hitokoto": "一定要爱着点什么，恰似草木对光阴的钟情。",
    "from": "汪曾祺《人间草木》"
  },
  {
    "hitokoto": "一个人只拥有此生此世是不够的，他还应该拥有诗意的世界。",
    "from": "王小波《万寿寺》"
  },
  {
    "hitokoto": "从前的日色变得慢，车，马，邮件都慢，一生只够爱一个人。",
    "from": "木心《从前慢》"
  },
  {
    "hitokoto": "你要做一个披荆斩棘无所不能的女英雄，直到遇见能托付一生的人，再做一个瓶盖都拧不开的小公主。",
    "from": "网络"
  },
  {
    "hitokoto": "如果有来生，要做一棵树，站成永恒，没有悲欢的姿势。",
    "from": "三毛《如果有来生》"
  },
  {
    "hitokoto": "活在这珍贵的人间，太阳强烈，水波温柔。",
    "from": "海子《活在珍贵的人间》"
  },
  {
    "hitokoto": "黑夜给了我黑色的眼睛，我却用它寻找光明。",
    "from": "顾城《一代人》"
  },
  {
    "hitokoto": "你顺手挽住火焰，化作漫天大雪。",
    "from": "北岛《青灯》"
  },
  {
    "hitokoto": "人生本来如此：喜欢的事自然可以坚持，不喜欢的怎么也长久不了。",
    "from": "村上春树《人生马拉松》"
  },
  {
    "hitokoto": "过去都是假的，回忆是一条没有归途的路。",
    "from": "加西亚·马尔克斯《百年孤独》"
  },
  {
    "hitokoto": "生活不能等待别人来安排，要自己去争取和奋斗。",
    "from": "路遥《平凡的世界》"
  },
  {
    "hitokoto": "人生最遗憾的，莫过于，轻易地放弃了不该放弃的，固执地坚持了不该坚持的。",
    "from": "柏拉图"
  },
  {
    "hitokoto": "我们一路奋战，不是为了改变世界，而是为了不让世界改变我们。",
    "from": "《熔炉》"
  },
  {
    "hitokoto": "有些鸟儿是关不住的，它们的每一片羽毛都闪耀着自由的光辉。",
    "from": "《肖申克的救赎》"
  },
  {
    "hitokoto": "生活就像一盒巧克力，你永远不知道下一颗是什么味道。",
    "from": "《阿甘正传》"
  },
  {
    "hitokoto": "如果再也不能见到你，祝你早安，午安，晚安。",
    "from": "《楚门的世界》"
  },
  {
    "hitokoto": "希望是一个好东西，也许是最好的东西，好东西是不会消亡的。",
    "from": "《肖申克的救赎》"
  },
  {
    "hitokoto": "一生那么短，遗忘又那么漫长。",
    "from": "《泰坦尼克号》"
  },
  {
    "hitokoto": "不要温顺地走入那个良夜。",
    "from": "《星际穿越》"
  },
  {
    "hitokoto": "死亡不是生命的终点，遗忘才是。",
    "from": "《寻梦环游记》"
  },
  {
    "hitokoto": "无论你成为什么样的人，无论你走到哪里，我都永远爱你。",
    "from": "《瞬息全宇宙》"
  },
  {
    "hitokoto": "为你，千千万万遍。",
    "from": "《追风筝的人》"
  },
  {
    "hitokoto": "我命由我不由天！",
    "from": "《哪吒之魔童降世》"
  },
  {
    "hitokoto": "只要记住你的名字，不管你在世界的哪个地方，我一定会，去见你。",
    "from": "《你的名字。》"
  },
  {
    "hitokoto": "隐约雷鸣，阴霾天空，但盼风雨来，能留你在此。",
    "from": "《言叶之庭》"
  },
  {
    "hitokoto": "世界这么大，人生这么长，总会有这么一个人，让你想要温柔地对待。",
    "from": "《哈尔的移动城堡》"
  },
  {
    "hitokoto": "人生就是一列开往坟墓的列车，路途上会有很多站，很难有人可以自始至终陪着走完。",
    "from": "《千与千寻》"
  },
  {
    "hitokoto": "起风了，唯有努力生存。",
    "from": "《起风了》"
  },
  {
    "hitokoto": "不管你曾经被伤害得有多深，总会有一个人的出现，让你原谅之前生活对你所有的刁难。",
    "from": "《幽灵公主》"
  },
  {
    "hitokoto": "无法舍弃两个方中的任何一方，那不是温柔，那不过是软弱罢了。",
    "from": "《东京喰种》"
  },
  {
    "hitokoto": "如果结果不如你所愿，就在尘埃落定前奋力一搏。",
    "from": "《夏目友人帐》"
  },
  {
    "hitokoto": "隐约雷鸣，阴霾天空，即使天无雨，我亦留此地。",
    "from": "《言叶之庭》"
  },
  {
    "hitokoto": "只要有想见的人，就不再是孤身一人了。",
    "from": "《夏目友人帐》"
  },
  {
    "hitokoto": "或许前路永夜，即便如此我也要前进，因为星光即使微弱也会为我照亮前路。",
    "from": "《四月是你的谎言》"
  },
  {
    "hitokoto": "不管前方的路有多苦，只要走的方向正确，不管多么崎岖不平，都比站在原地更接近幸福。",
    "from": "《千与千寻》"
  },
  {
    "hitokoto": "我们总是在意自己错过太多，却不曾注意自己拥有多少。",
    "from": "《未闻花名》"
  },
  {
    "hitokoto": "愿你有一天能和你最重要的人重逢。",
    "from": "《可塑性记忆》"
  },
  {
    "hitokoto": "温柔正确的人总是难以生存，因为这世界既不温柔，也不正确。",
    "from": "《我的青春恋爱物语果然有问题》"
  },
  {
    "hitokoto": "心之所向，素履以往；生如逆旅，一苇以航。",
    "from": "七堇年《尘曲》"
  },
  {
    "hitokoto": "岁月不居，时节如流。",
    "from": "孔融《论盛孝章书》"
  },
  {
    "hitokoto": "凡是过往，皆为序章。",
    "from": "莎士比亚《暴风雨》"
  },
  {
    "hitokoto": "前途似海，来日方长。",
    "from": "梁启超《少年中国说》"
  },
  {
    "hitokoto": "以梦为马，不负韶华。",
    "from": "海子"
  },
  {
    "hitokoto": "愿有岁月可回首，且以深情共白头。",
    "from": "冯唐《三十六大》"
  },
  {
    "hitokoto": "海底月是天上月，眼前人是心上人。",
    "from": "张爱玲《倾城之恋》"
  },
  {
    "hitokoto": "你若盛开，清风自来。",
    "from": "三毛"
  },
  {
    "hitokoto": "繁华尽处，寻一处无人山谷，建一木制小屋，铺一青石小路，与你晨钟暮鼓，安之若素。",
    "from": "网络"
  },
  {
    "hitokoto": "白茶清欢无别事，我在等风也等你。",
    "from": "网络"
  },
  {
    "hitokoto": "南风知我意，吹梦到西洲。",
    "from": "《西洲曲》"
  },
  {
    "hitokoto": "我见青山多妩媚，料青山见我应如是。",
    "from": "辛弃疾《贺新郎·甚矣吾衰矣》"
  },
  {
    "hitokoto": "晓看天色暮看云，行也思君，坐也思君。",
    "from": "唐寅《一剪梅·雨打梨花深闭门》"
  },
  {
    "hitokoto": "玲珑骰子安红豆，入骨相思知不知。",
    "from": "温庭筠《南歌子词二首》"
  },
  {
    "hitokoto": "曾经沧海难为水，除却巫山不是云。",
    "from": "元稹《离思五首·其四》"
  },
  {
    "hitokoto": "两情若是久长时，又岂在朝朝暮暮。",
    "from": "秦观《鹊桥仙·纤云弄巧》"
  },
  {
    "hitokoto": "身无彩凤双飞翼，心有灵犀一点通。",
    "from": "李商隐《无题》"
  },
  {
    "hitokoto": "人生得意须尽欢，莫使金樽空对月。",
    "from": "李白《将进酒》"
  },
  {
    "hitokoto": "天生我材必有用，千金散尽还复来。",
    "from": "李白《将进酒》"
  },
  {
    "hitokoto": "莫愁前路无知己，天下谁人不识君。",
    "from": "高适《别董大二首》"
  },
  {
    "hitokoto": "大鹏一日同风起，扶摇直上九万里。",
    "from": "李白《上李邕》"
  },
  {
    "hitokoto": "千淘万漉虽辛苦，吹尽狂沙始到金。",
    "from": "刘禹锡《浪淘沙九首》"
  },
  {
    "hitokoto": "沉舟侧畔千帆过，病树前头万木春。",
    "from": "刘禹锡《酬乐天扬州初逢席上见赠》"
  },
  {
    "hitokoto": "不畏浮云遮望眼，自缘身在最高层。",
    "from": "王安石《登飞来峰》"
  },
  {
    "hitokoto": "会当凌绝顶，一览众山小。",
    "from": "杜甫《望岳》"
  },
  {
    "hitokoto": "路漫漫其修远兮，吾将上下而求索。",
    "from": "屈原《离骚》"
  },
  {
    "hitokoto": "天行健，君子以自强不息。",
    "from": "《周易》"
  },
  {
    "hitokoto": "地势坤，君子以厚德载物。",
    "from": "《周易》"
  },
  {
    "hitokoto": "非淡泊无以明志，非宁静无以致远。",
    "from": "诸葛亮《诫子书》"
  },
  {
    "hitokoto": "博观而约取，厚积而薄发。",
    "from": "苏轼《稼说送张琥》"
  },
  {
    "hitokoto": "纸上得来终觉浅，绝知此事要躬行。",
    "from": "陆游《冬夜读书示子聿》"
  },
  {
    "hitokoto": "读书破万卷，下笔如有神。",
    "from": "杜甫《奉赠韦左丞丈二十二韵》"
  },
  {
    "hitokoto": "黑发不知勤学早，白首方悔读书迟。",
    "from": "颜真卿《劝学》"
  },
  {
    "hitokoto": "少壮不努力，老大徒伤悲。",
    "from": "《长歌行》"
  },
  {
    "hitokoto": "一寸光阴一寸金，寸金难买寸光阴。",
    "from": "《增广贤文》"
  },
  {
    "hitokoto": "明日复明日，明日何其多。我生待明日，万事成蹉跎。",
    "from": "钱福《明日歌》"
  },
  {
    "hitokoto": "盛年不重来，一日难再晨。及时当勉励，岁月不待人。",
    "from": "陶渊明《杂诗》"
  },
  {
    "hitokoto": "劝君莫惜金缕衣，劝君惜取少年时。",
    "from": "杜秋娘《金缕衣》"
  },
  {
    "hitokoto": "花有重开日，人无再少年。",
    "from": "关汉卿《窦娥冤》"
  },
  {
    "hitokoto": "落红不是无情物，化作春泥更护花。",
    "from": "龚自珍《己亥杂诗》"
  },
  {
    "hitokoto": "春蚕到死丝方尽，蜡炬成灰泪始干。",
    "from": "李商隐《无题》"
  },
  {
    "hitokoto": "先天下之忧而忧，后天下之乐而乐。",
    "from": "范仲淹《岳阳楼记》"
  },
  {
    "hitokoto": "鞠躬尽瘁，死而后已。",
    "from": "诸葛亮《后出师表》"
  },
  {
    "hitokoto": "天下兴亡，匹夫有责。",
    "from": "顾炎武"
  },
  {
    "hitokoto": "苟利国家生死以，岂因祸福避趋之。",
    "from": "林则徐《赴戍登程口占示家人》"
  },
  {
    "hitokoto": "人生自古谁无死？留取丹心照汗青。",
    "from": "文天祥《过零丁洋》"
  },
  {
    "hitokoto": "粉骨碎身浑不怕，要留清白在人间。",
    "from": "于谦《石灰吟》"
  },
  {
    "hitokoto": "千磨万击还坚劲，任尔东西南北风。",
    "from": "郑燮《竹石》"
  },
  {
    "hitokoto": "宝剑锋从磨砺出，梅花香自苦寒来。",
    "from": "《警世贤文》"
  },
  {
    "hitokoto": "长风破浪会有时，直挂云帆济沧海。",
    "from": "李白《行路难》"
  },
  {
    "hitokoto": "俱怀逸兴壮思飞，欲上青天揽明月。",
    "from": "李白《宣州谢朓楼饯别校书叔云》"
  },
  {
    "hitokoto": "仰天大笑出门去，我辈岂是蓬蒿人。",
    "from": "李白《南陵别儿童入京》"
  },
  {
    "hitokoto": "安能摧眉折腰事权贵，使我不得开心颜。",
    "from": "李白《梦游天姥吟留别》"
  },
  {
    "hitokoto": "天生我材必有用，千金散尽还复来。",
    "from": "李白《将进酒》"
  },
  {
    "hitokoto": "王侯将相宁有种乎？",
    "from": "司马迁《陈涉世家》"
  },
  {
    "hitokoto": "燕雀安知鸿鹄之志哉？",
    "from": "司马迁《陈涉世家》"
  },
  {
    "hitokoto": "老骥伏枥，志在千里。烈士暮年，壮心不已。",
    "from": "曹操《龟虽寿》"
  },
  {
    "hitokoto": "生当作人杰，死亦为鬼雄。",
    "from": "李清照《夏日绝句》"
  },
  {
    "hitokoto": "愿将腰下剑，直为斩楼兰。",
    "from": "李白《塞下曲》"
  },
  {
    "hitokoto": "黄沙百战穿金甲，不破楼兰终不还。",
    "from": "王昌龄《从军行》"
  },
  {
    "hitokoto": "但使龙城飞将在，不教胡马度阴山。",
    "from": "王昌龄《出塞》"
  },
  {
    "hitokoto": "醉卧沙场君莫笑，古来征战几人回。",
    "from": "王翰《凉州词》"
  },
  {
    "hitokoto": "葡萄美酒夜光杯，欲饮琵琶马上催。",
    "from": "王翰《凉州词》"
  },
  {
    "hitokoto": "羌笛何须怨杨柳，春风不度玉门关。",
    "from": "王之涣《凉州词》"
  },
  {
    "hitokoto": "大漠孤烟直，长河落日圆。",
    "from": "王维《使至塞上》"
  },
  {
    "hitokoto": "明月松间照，清泉石上流。",
    "from": "王维《山居秋暝》"
  },
  {
    "hitokoto": "空山不见人，但闻人语响。",
    "from": "王维《鹿柴》"
  },
  {
    "hitokoto": "独坐幽篁里，弹琴复长啸。",
    "from": "王维《竹里馆》"
  },
  {
    "hitokoto": "红豆生南国，春来发几枝。愿君多采撷，此物最相思。",
    "from": "王维《相思》"
  },
  {
    "hitokoto": "劝君更尽一杯酒，西出阳关无故人。",
    "from": "王维《送元二使安西》"
  },
  {
    "hitokoto": "海内存知己，天涯若比邻。",
    "from": "王勃《送杜少府之任蜀州》"
  },
  {
    "hitokoto": "落霞与孤鹜齐飞，秋水共长天一色。",
    "from": "王勃《滕王阁序》"
  },
  {
    "hitokoto": "老当益壮，宁移白首之心？穷且益坚，不坠青云之志。",
    "from": "王勃《滕王阁序》"
  },
  {
    "hitokoto": "关山难越，谁悲失路之人？萍水相逢，尽是他乡之客。",
    "from": "王勃《滕王阁序》"
  },
  {
    "hitokoto": "天高地迥，觉宇宙之无穷；兴尽悲来，识盈虚之有数。",
    "from": "王勃《滕王阁序》"
  },
  {
    "hitokoto": "白日依山尽，黄河入海流。欲穷千里目，更上一层楼。",
    "from": "王之涣《登鹳雀楼》"
  },
  {
    "hitokoto": "春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。",
    "from": "孟浩然《春晓》"
  },
  {
    "hitokoto": "野火烧不尽，春风吹又生。",
    "from": "白居易《赋得古原草送别》"
  },
  {
    "hitokoto": "同是天涯沦落人，相逢何必曾相识。",
    "from": "白居易《琵琶行》"
  },
  {
    "hitokoto": "在天愿作比翼鸟，在地愿为连理枝。",
    "from": "白居易《长恨歌》"
  },
  {
    "hitokoto": "回眸一笑百媚生，六宫粉黛无颜色。",
    "from": "白居易《长恨歌》"
  },
  {
    "hitokoto": "后宫佳丽三千人，三千宠爱在一身。",
    "from": "白居易《长恨歌》"
  },
  {
    "hitokoto": "七月七日长生殿，夜半无人私语时。",
    "from": "白居易《长恨歌》"
  },
  {
    "hitokoto": "代码写得好，头发掉得早；Bug 修得快，加班跑不掉。",
    "from": "程序员日常"
  },
  {
    "hitokoto": "Talk is cheap. Show me the code.",
    "from": "Linus Torvalds"
  },
  {
    "hitokoto": "人生苦短，我用 Python。",
    "from": "Bruce Eckel"
  },
  {
    "hitokoto": "任何一个傻瓜都能写出计算机可以理解的代码。唯有写出人类容易理解的代码，才是优秀的程序员。",
    "from": "Martin Fowler"
  },
  {
    "hitokoto": "如果调试一个程序让你花了很多时间，那么写这个程序的家伙一定是个天才。",
    "from": "《编程格言》"
  },
  {
    "hitokoto": "程序是永远写不完的，Bug 是永远修不完的，只有咖啡是永远喝不够的。",
    "from": "极客语录"
  },
  {
    "hitokoto": "不要因为走得太远，忘了我们为什么出发。",
    "from": "纪伯伦"
  },
  {
    "hitokoto": "世界上只有一种失败，那就是半途而废。",
    "from": "网络"
  },
  {
    "hitokoto": "你要悄悄拔尖，然后惊艳所有人。",
    "from": "网络"
  },
  {
    "hitokoto": "半山腰总是最挤的，你得去山顶看看。",
    "from": "网络"
  },
  {
    "hitokoto": "去发光，而不是被照亮。",
    "from": "网络"
  },
  {
    "hitokoto": "慢慢来，谁还没有一个努力的过程。",
    "from": "网络"
  },
  {
    "hitokoto": "所有的不期而遇，都是蓄谋已久的惊喜。",
    "from": "网络"
  },
  {
    "hitokoto": "熬过无人问津的日子，才有诗和远方。",
    "from": "网络"
  },
  {
    "hitokoto": "你未必光芒万丈，但始终温暖有光。",
    "from": "网络"
  },
  {
    "hitokoto": "保持热爱，总会有很多瞬间告诉你，生活温柔且浪漫。",
    "from": "网络"
  },
  {
    "hitokoto": "满地都是六便士，他却抬头看见了月亮。",
    "from": "毛姆"
  },
  {
    "hitokoto": "生活明朗，万物可爱，人间值得，未来可期。",
    "from": "丰子恺"
  },
  {
    "hitokoto": "心之所向，素履以往；生如逆旅，一苇以航。",
    "from": "七堇年"
  },
  {
    "hitokoto": "凡是过往，皆为序章。",
    "from": "莎士比亚"
  },
  {
    "hitokoto": "愿你在冷铁卷刃前，得以窥见天光。",
    "from": "《有匪》"
  },
  {
    "hitokoto": "我偏要一条路走到黑，偏要看看那尽头到底是什么。",
    "from": "网络"
  },
  {
    "hitokoto": "世界上有两个我，一个想回家，一个想远行。",
    "from": "网络"
  },
  {
    "hitokoto": "总要热爱点什么，比如对生活的向往。",
    "from": "网络"
  },
  {
    "hitokoto": "把烦心事丢掉，腾出地方装鲜花。",
    "from": "网络"
  },
  {
    "hitokoto": "请保持你心里的光，因为你不知道谁会借此走出黑暗。",
    "from": "网络"
  },
  {
    "hitokoto": "我们终其一生，就是要摆脱别人的期待，找到真正的自己。",
    "from": "《无声告白》"
  },
  {
    "hitokoto": "热爱可抵岁月漫长，温柔可挡艰难时光。",
    "from": "网络"
  },
  {
    "hitokoto": "你可以回头，但不可以往回走，逆行是全责。",
    "from": "网络"
  },
  {
    "hitokoto": "别慌，月亮也正在大海某处迷茫。",
    "from": "网络"
  },
  {
    "hitokoto": "这世界哪怕再叫人失望，也有一种叫美好的东西在暗地里生长。",
    "from": "《你好，旧时光》"
  },
  {
    "hitokoto": "愿你所有的努力都不白费，所想的都能如愿，所做的都能实现。",
    "from": "网络"
  },
  {
    "hitokoto": "即使身处阴沟，也要仰望星空。",
    "from": "王尔德"
  },
  {
    "hitokoto": "只要还有明天，今天就永远是起跑线。",
    "from": "网络"
  },
  {
    "hitokoto": "未知苦处，不信神佛。",
    "from": "Priest《杀破狼》"
  },
  {
    "hitokoto": "我连魂魄都是黑的，唯独心尖上一点干干净净地放着你。",
    "from": "Priest《镇魂》"
  },
  {
    "hitokoto": "为你战死，是我至高无上的荣耀。",
    "from": "墨香铜臭《天官赐福》"
  },
  {
    "hitokoto": "未知全貌，不予置评。",
    "from": "墨香铜臭《魔道祖师》"
  },
  {
    "hitokoto": "此生无悔入华夏，来世还在种花家。",
    "from": "《那年那兔那些事》"
  },
  {
    "hitokoto": "真相只有一个。",
    "from": "《名侦探柯南》"
  },
  {
    "hitokoto": "人的梦想，是不会终止的！",
    "from": "《海贼王》"
  },
  {
    "hitokoto": "如果这是你所谓的正义，那我宁愿化身邪恶。",
    "from": "《反叛的鲁路修》"
  },
  {
    "hitokoto": "藏好了吗？我要开始找你了。",
    "from": "《鬼灭之刃》"
  },
  {
    "hitokoto": "无论你在哪里，我都会找到你。",
    "from": "《你的名字》"
  },
  {
    "hitokoto": "错的不是我，是这个世界。",
    "from": "《东京喰种》"
  },
  {
    "hitokoto": "因为喜欢你，所以我愿意为你变得更强。",
    "from": "《火影忍者》"
  },
  {
    "hitokoto": "原谅我吧，佐助，这是最后一次了。",
    "from": "《火影忍者》"
  },
  {
    "hitokoto": "教练，我想打篮球。",
    "from": "《灌篮高手》"
  },
  {
    "hitokoto": "我可是要成为海贼王的男人！",
    "from": "《海贼王》"
  },
  {
    "hitokoto": "即使是一秒钟，我也想和你在一起。",
    "from": "《犬夜叉》"
  },
  {
    "hitokoto": "不可以逃避！如果你逃了，就永远也赢不了。",
    "from": "《排球少年》"
  },
  {
    "hitokoto": "人类的赞歌就是勇气的赞歌，人类的伟大就是勇气的伟大！",
    "from": "《JOJO的奇妙冒险》"
  },
  {
    "hitokoto": "你的下一句话是……",
    "from": "《JOJO的奇妙冒险》"
  },
  {
    "hitokoto": "我们终会重逢，在无限延伸的梦想尽头。",
    "from": "《数码宝贝》"
  },
  {
    "hitokoto": "夜阑卧听风吹雨，铁马是你，冰河也是你。",
    "from": "网络改编"
  },
  {
    "hitokoto": "所爱隔山海，山海皆可平。",
    "from": "网络"
  },
  {
    "hitokoto": "这个世界的温柔，来自于你的强大。",
    "from": "网络"
  },
  {
    "hitokoto": "别害怕，宇宙都温柔。",
    "from": "网络"
  },
  {
    "hitokoto": "万事尽头，终将如意。",
    "from": "网络"
  },
  {
    "hitokoto": "不要因为5%的负面评价，去否定自己100%的努力。",
    "from": "何炅"
  },
  {
    "hitokoto": "可以一落千丈，但我偏要一鸣惊人。",
    "from": "网络"
  },
  {
    "hitokoto": "趁着年轻，去经历，去后悔，去热爱。",
    "from": "网络"
  },
  {
    "hitokoto": "没有人能让你输，除非你不想赢。",
    "from": "网络"
  },
  {
    "hitokoto": "风乍起，合当奋意向人生。",
    "from": "《起风了》"
  },
  {
    "hitokoto": "既然选择了远方，便只顾风雨兼程。",
    "from": "汪国真"
  },
  {
    "hitokoto": "不怕路长，只怕心老。",
    "from": "网络"
  },
  {
    "hitokoto": "愿你出走半生，归来仍是少年。",
    "from": "网络"
  },
  {
    "hitokoto": "既然认准了一条路，何必去打听要走多久。",
    "from": "网络"
  },
  {
    "hitokoto": "有些路很远，走下去会很累，可是不走，会后悔。",
    "from": "网络"
  },
  {
    "hitokoto": "现在不玩命，将来命玩你。",
    "from": "网络"
  },
  {
    "hitokoto": "发光不是太阳的权利，你也可以。",
    "from": "网络"
  },
  {
    "hitokoto": "没有太晚的开始，不如就从今天行动。",
    "from": "网络"
  },
  {
    "hitokoto": "你的好运气藏在你的实力里，也藏在你不为人知的努力里。",
    "from": "网络"
  },
  {
    "hitokoto": "把努力当成一种习惯，而不是一时的热血。",
    "from": "网络"
  },
  {
    "hitokoto": "不为模糊不清的未来担忧，只为清清楚楚的现在努力。",
    "from": "网络"
  },
  {
    "hitokoto": "生活不是等待风暴过去，而是学会在雨中翩翩起舞。",
    "from": "网络"
  },
  {
    "hitokoto": "万物皆有裂痕，那是光照进来的地方。",
    "from": "莱昂纳德·科恩"
  },
  {
    "hitokoto": "不要着急，最好的总会在最不经意的时候出现。",
    "from": "网络"
  },
  {
    "hitokoto": "慢品人间烟火色，闲观万事岁月长。",
    "from": "网络"
  },
  {
    "hitokoto": "岁月极美，在于它必然的流逝。春花、秋月、夏日、冬雪。",
    "from": "三毛"
  },
  {
    "hitokoto": "生活原本沉闷，但跑起来就有风。",
    "from": "网络"
  },
  {
    "hitokoto": "知世故而不世故，善自嘲而不嘲人。",
    "from": "网络"
  },
  {
    "hitokoto": "人间烟火气，最抚凡人心。",
    "from": "网络"
  },
  {
    "hitokoto": "心若向阳，无谓悲伤。",
    "from": "网络"
  },
  {
    "hitokoto": "落俗不可避免，浪漫至死不渝。",
    "from": "网络"
  },
  {
    "hitokoto": "热爱漫无边际，生活自有分寸。",
    "from": "网络"
  },
  {
    "hitokoto": "愿所有的后会有期，都是它日的别来无恙。",
    "from": "网络"
  },
  {
    "hitokoto": "把圈子变小，把语速放缓，把心放宽，把生活打理简单。",
    "from": "网络"
  },
  {
    "hitokoto": "外向是生活所需，孤独是自我享受。",
    "from": "网络"
  },
  {
    "hitokoto": "把期望降到最低，所有的遇见都是礼物。",
    "from": "网络"
  },
  {
    "hitokoto": "温柔的晚风，一定能吹散很多不愉快吧。",
    "from": "网络"
  },
  {
    "hitokoto": "总要删除一些难过，才能容纳更多快乐。",
    "from": "网络"
  },
  {
    "hitokoto": "把身体照顾好，把喜欢的事做好，把重要的人待好，你要的一切都在路上。",
    "from": "网络"
  },
  {
    "hitokoto": "不必太纠结于当下，也不必太忧虑未来。",
    "from": "村上春树"
  },
  {
    "hitokoto": "当你穿过了暴风雨，你就不再是原来那个人。",
    "from": "村上春树"
  },
  {
    "hitokoto": "你要做一个不动声色的大人了，不准情绪化，不准偷偷想念，不准回头看。",
    "from": "村上春树"
  },
  {
    "hitokoto": "迷失的人迷失了，相逢的人会再相逢。",
    "from": "村上春树"
  },
  {
    "hitokoto": "哪有人喜欢孤独，不过是不喜欢失望罢了。",
    "from": "村上春树"
  },
  {
    "hitokoto": "死并非生的对立面，而作为生的一部分永存。",
    "from": "村上春树"
  },
  {
    "hitokoto": "不是所有的鱼都会生活在同一片海里。",
    "from": "村上春树"
  },
  {
    "hitokoto": "我一直以为人是慢慢变老的，其实不是，人是一瞬间变老的。",
    "from": "村上春树"
  },
  {
    "hitokoto": "没有小确幸的人生，不过是干巴巴的沙漠罢了。",
    "from": "村上春树"
  },
  {
    "hitokoto": "如果我爱你，而你也正巧爱我。你头发乱了时候，我会笑笑替你拨一拨，然后，手还留恋地在你发上多待几秒。",
    "from": "村上春树"
  },
  {
    "hitokoto": "每一个不曾起舞的日子，都是对生命的辜负。",
    "from": "尼采"
  },
  {
    "hitokoto": "当你凝视深渊时，深渊也在凝视着你。",
    "from": "尼采"
  },
  {
    "hitokoto": "那些杀不死我的，终将使我更强大。",
    "from": "尼采"
  },
  {
    "hitokoto": "如果这世界上真有奇迹，那只是努力的另一个名字。",
    "from": "尼采"
  },
  {
    "hitokoto": "白昼之光，岂知夜色之深。",
    "from": "尼采"
  },
  {
    "hitokoto": "我生来就是高山而非溪流，我欲于群峰之巅俯视平庸的沟壑。",
    "from": "张桂梅"
  },
  {
    "hitokoto": "我生来就是人杰而非草芥，我站在伟人之肩藐视卑微的懦夫。",
    "from": "张桂梅"
  },
  {
    "hitokoto": "若你决定灿烂，山无遮，海无拦。",
    "from": "撒贝宁"
  },
  {
    "hitokoto": "生活一半是回忆，一半是继续。",
    "from": "网络"
  },
  {
    "hitokoto": "岁月不饶人，我亦未曾饶过岁月。",
    "from": "木心"
  },
  {
    "hitokoto": "不知道原谅什么，诚觉世事尽可原谅。",
    "from": "木心"
  },
  {
    "hitokoto": "我习于冷，志于成冰。",
    "from": "木心"
  },
  {
    "hitokoto": "常想一二，不思八九，事事如意。",
    "from": "林清玄"
  },
  {
    "hitokoto": "以清净心看世界，以欢喜心过生活，以平常心生情味，以柔软心除挂碍。",
    "from": "林清玄"
  },
  {
    "hitokoto": "心美一切皆美，情深万象皆深。",
    "from": "林清玄"
  },
  {
    "hitokoto": "温柔半两，从容一生。",
    "from": "网络"
  },
  {
    "hitokoto": "人间忽晚，山河已秋。",
    "from": "网络"
  },
  {
    "hitokoto": "众生皆苦，唯有自渡。",
    "from": "网络"
  },
  {
    "hitokoto": "星光不问赶路人，时光不负有心人。",
    "from": "网络"
  },
  {
    "hitokoto": "所有的丧，都是因为没钱。",
    "from": "网络"
  },
  {
    "hitokoto": "只要我吃得够快，体重就追不上我。",
    "from": "网络"
  },
  {
    "hitokoto": "间歇性踌躇满志，持续性混吃等死。",
    "from": "网络"
  },
  {
    "hitokoto": "我这人没什么缺点，唯一的缺点就是缺点钱。",
    "from": "网络"
  },
  {
    "hitokoto": "何以解忧，唯有暴富。",
    "from": "网络"
  },
  {
    "hitokoto": "今天的事今天做，明天的事明天再说。",
    "from": "网络"
  },
  {
    "hitokoto": "只要我躺得够快，困难就追不上我。",
    "from": "网络"
  },
  {
    "hitokoto": "每天最大的运动量，就是翻身。",
    "from": "网络"
  },
  {
    "hitokoto": "别问我为什么单身，我是神仙，神仙和凡人是不可以谈恋爱的。",
    "from": "网络"
  },
  {
    "hitokoto": "熬夜一时爽，一直熬夜一直爽。",
    "from": "网络"
  },
  {
    "hitokoto": "我除了长得好看，一无是处。",
    "from": "网络"
  },
  {
    "hitokoto": "别人琴棋书画样样精通，我煎炒烹炸什么都吃。",
    "from": "网络"
  },
  {
    "hitokoto": "有时候不努力一把，你都不知道什么叫绝望。",
    "from": "网络"
  },
  {
    "hitokoto": "你若安好，那还得了。",
    "from": "网络"
  },
  {
    "hitokoto": "不要随便跟人吵架，因为你不知道对方的真实身份。",
    "from": "网络"
  },
  {
    "hitokoto": "人生就像打电话，不是你先挂，就是我先挂。",
    "from": "网络"
  },
  {
    "hitokoto": "长得好看的才叫吃货，长得丑的叫饭桶。",
    "from": "网络"
  },
  {
    "hitokoto": "生活不止眼前的苟且，还有读不懂的诗和到不了的远方。",
    "from": "网络"
  },
  {
    "hitokoto": "别沮丧，生活就像心电图，一帆风顺你就挂了。",
    "from": "网络"
  },
  {
    "hitokoto": "我的意中人是个盖世英雄，有一天他会踩着七色云彩来娶我。",
    "from": "《大话西游》"
  },
  {
    "hitokoto": "曾经有一份真挚的爱情摆在我面前，我没有珍惜……",
    "from": "《大话西游》"
  },
  {
    "hitokoto": "做人如果没有梦想，那跟咸鱼有什么分别？",
    "from": "《少林足球》"
  },
  {
    "hitokoto": "如果上天能够给我一个再来一次的机会，我会对那个女孩子说三个字：我爱你。",
    "from": "《大话西游》"
  },
  {
    "hitokoto": "我猜中了前头，可是我猜不着这结局。",
    "from": "《大话西游》"
  },
  {
    "hitokoto": "喜新厌旧不是病，不断原谅才有病。",
    "from": "网络"
  },
  {
    "hitokoto": "不要因为没人为你鼓掌，就放弃你的梦想。",
    "from": "网络"
  },
  {
    "hitokoto": "没有谁的生活会一直完美，但无论什么时候，都要看着前方，满怀希望就会所向披靡。",
    "from": "网络"
  },
  {
    "hitokoto": "给岁月以文明，而不是给文明以岁月。",
    "from": "刘慈欣《三体》"
  },
  {
    "hitokoto": "弱小和无知不是生存的障碍，傲慢才是。",
    "from": "刘慈欣《三体》"
  },
  {
    "hitokoto": "我消灭你，与你无关。",
    "from": "刘慈欣《三体》"
  },
  {
    "hitokoto": "不要回答！不要回答！不要回答！",
    "from": "刘慈欣《三体》"
  },
  {
    "hitokoto": "宇宙就是一座黑暗森林，每个文明都是带枪的猎人。",
    "from": "刘慈欣《三体》"
  },
  {
    "hitokoto": "我们是虫子，但我们绝不认输。",
    "from": "刘慈欣《三体》"
  },
  {
    "hitokoto": "在群星之间，有着无限的可能。",
    "from": "《星际迷航》"
  },
  {
    "hitokoto": "不要恐慌。",
    "from": "道格拉斯·亚当斯《银河系漫游指南》"
  },
  {
    "hitokoto": "决定我们成为什么样人的，不是我们的能力，而是我们的选择。",
    "from": "J.K.罗琳《哈利·波特》"
  },
  {
    "hitokoto": "我们都有光明的一面和黑暗的一面，关键在于我们选择哪一面去行动。",
    "from": "《哈利·波特》"
  },
  {
    "hitokoto": "哪怕是最渺小的人，也能改变未来的走向。",
    "from": "《指环王》"
  },
  {
    "hitokoto": "这世上一定存在着善良，值得我们奋战到底。",
    "from": "《指环王》"
  },
  {
    "hitokoto": "人生就像一场戏，因为有缘才相聚。",
    "from": "《霸王别姬》"
  },
  {
    "hitokoto": "说好的一辈子，差一年、一个月、一天、一个时辰，都不算一辈子！",
    "from": "《霸王别姬》"
  },
  {
    "hitokoto": "不疯魔，不成活。",
    "from": "《霸王别姬》"
  },
  {
    "hitokoto": "死亡是必然的，但我们可以选择如何面对它。",
    "from": "《哈利·波特》"
  },
  {
    "hitokoto": "如果打算爱一个人，你要想清楚，是否愿意为了他，放弃如上帝般自由的心灵，从此心甘情愿有了羁绊。",
    "from": "菲茨杰拉德《了不起的盖茨比》"
  },
  {
    "hitokoto": "每逢你想要批评任何人的时候，你就记住，这个世界上所有的人，并不是个个都有过你拥有的那些优越条件。",
    "from": "菲茨杰拉德《了不起的盖茨比》"
  },
  {
    "hitokoto": "于是我们奋力前行，小舟逆水而上，不断地被浪潮推回到过去。",
    "from": "菲茨杰拉德《了不起的盖茨比》"
  },
  {
    "hitokoto": "傲慢让别人无法来爱我，偏见让我无法去爱别人。",
    "from": "简·奥斯汀《傲慢与偏见》"
  },
  {
    "hitokoto": "将感情埋藏得太深有时是件坏事。如果一个女人掩饰了对自己所爱的男子的感情，她也许就失去了得到他的机会。",
    "from": "简·奥斯汀《傲慢与偏见》"
  },
  {
    "hitokoto": "我越是孤独，越是没有朋友，越是没有支持，我就得越尊重我自己。",
    "from": "夏洛蒂·勃朗特《简·爱》"
  },
  {
    "hitokoto": "你以为我贫穷、相貌平平就没有感情吗？我向你起誓：如果上帝赐予我财富和美貌，我会让你难于离开我，就像我现在难于离开你一样。",
    "from": "夏洛蒂·勃朗特《简·爱》"
  },
  {
    "hitokoto": "生存还是毁灭，这是一个值得考虑的问题。",
    "from": "莎士比亚《哈姆雷特》"
  },
  {
    "hitokoto": "脆弱啊，你的名字是女人。",
    "from": "莎士比亚《哈姆雷特》"
  },
  {
    "hitokoto": "全世界是一个舞台，所有的男男女女不过是一些演员。",
    "from": "莎士比亚《皆大欢喜》"
  },
  {
    "hitokoto": "爱是一种甜蜜的痛苦。",
    "from": "莎士比亚"
  },
  {
    "hitokoto": "不要指着月亮起誓，它是变化无常的。",
    "from": "莎士比亚《罗密欧与朱丽叶》"
  },
  {
    "hitokoto": "黑夜无论怎样悠长，白昼总会到来。",
    "from": "莎士比亚《麦克白》"
  },
  {
    "hitokoto": "世界上只有一种真正的英雄主义，那就是在认清生活的真相后依然热爱生活。",
    "from": "罗曼·罗兰《米开朗基罗传》"
  },
  {
    "hitokoto": "大部分人在二三十岁上就死去了，因为过了这个年龄，他们只是自己的影子，此后的余生则是在模仿自己中度过。",
    "from": "罗曼·罗兰《约翰·克利斯朵夫》"
  },
  {
    "hitokoto": "从来如此，便对么？",
    "from": "鲁迅《狂人日记》"
  },
  {
    "hitokoto": "其实地上本没有路，走的人多了，也便成了路。",
    "from": "鲁迅《故乡》"
  },
  {
    "hitokoto": "人类的悲欢并不相通，我只觉得他们吵闹。",
    "from": "鲁迅《小杂感》"
  },
  {
    "hitokoto": "愿中国青年都摆脱冷气，只是向上走，不必听自暴自弃者流的话。",
    "from": "鲁迅《热风》"
  },
  {
    "hitokoto": "悲剧将人生的有价值的东西毁灭给人看，喜剧将那无价值的撕破给人看。",
    "from": "鲁迅《再论雷峰塔的倒掉》"
  },
  {
    "hitokoto": "我翻开历史一查，这历史没有年代，歪歪斜斜的每页上都写着“仁义道德”几个字。我横竖睡不着，仔细看了半夜，才从字缝里看出字来，满本都写着两个字是“吃人”！",
    "from": "鲁迅《狂人日记》"
  },
  {
    "hitokoto": "让你难过的事情，有一天，你一定会笑着说出来。",
    "from": "《肖申克的救赎》"
  },
  {
    "hitokoto": "忙着去活，或者忙着去死。",
    "from": "《肖申克的救赎》"
  },
  {
    "hitokoto": "有些鸟儿是关不住的，它们的每一片羽毛都闪耀着自由的光辉。",
    "from": "《肖申克的救赎》"
  },
  {
    "hitokoto": "我希望太平洋的海水像我梦中那样蓝。",
    "from": "《肖申克的救赎》"
  },
  {
    "hitokoto": "我们注定要失去我们所爱的人，要不然我们怎么知道他们对我们有多么重要。",
    "from": "《返老还童》"
  },
  {
    "hitokoto": "你可以像疯狗一样对周围的一切愤愤不平，你可以诅咒命运，但是等到最后一刻，你还得平静的放手而去。",
    "from": "《返老还童》"
  },
  {
    "hitokoto": "一件事无论太晚或者太早，都不会阻拦你成为你想成为的那个人，这个过程没有时间的期限，只要你想，随时都可以开始。",
    "from": "《返老还童》"
  },
  {
    "hitokoto": "我用尽了全力，过着平凡的一生。",
    "from": "毛姆《月亮与六便士》"
  },
  {
    "hitokoto": "在爱情的事上如果你考虑起自尊心来，那只能有一个原因：实际上你还是最爱自己。",
    "from": "毛姆《月亮与六便士》"
  },
  {
    "hitokoto": "为了使灵魂宁静，一个人每天要做两件他不喜欢的事。",
    "from": "毛姆《月亮与六便士》"
  },
  {
    "hitokoto": "我用尽了全力，过着平凡的一生。",
    "from": "毛姆"
  },
  {
    "hitokoto": "满地都是六便士，他却抬头看见了月亮。",
    "from": "毛姆"
  },
  {
    "hitokoto": "人们宁愿去关心一个蹩脚电影演员的吃喝拉撒和鸡毛蒜皮，而不愿了解一个普通人波涛汹涌的内心世界。",
    "from": "路遥《平凡的世界》"
  },
  {
    "hitokoto": "生活不能等待别人来安排，要自己去争取和奋斗；而不论其结果是喜是悲，但可以慰藉的是，你总不枉在这世界上活了一场。",
    "from": "路遥《平凡的世界》"
  },
  {
    "hitokoto": "其实我们每个人的生活都是一个世界，即使最平凡的人也要为他生活的那个世界而奋斗。",
    "from": "路遥《平凡的世界》"
  },
  {
    "hitokoto": "人生啊，是这样不可预测，没有永恒的痛苦，也没有永恒的幸福，生活像流水一般，有时是那么平展，有时又是那么曲折。",
    "from": "路遥《平凡的世界》"
  },
  {
    "hitokoto": "生活总是让我们遍体鳞伤，但到后来，那些受伤的地方一定会变成我们最强壮的地方。",
    "from": "海明威《永别了，武器》"
  },
  {
    "hitokoto": "一个人可以被毁灭，但不能被打败。",
    "from": "海明威《老人与海》"
  },
  {
    "hitokoto": "现在不是去想缺少什么的时候，该想一想凭现有的东西你能做什么。",
    "from": "海明威《老人与海》"
  },
  {
    "hitokoto": "每一天都是一个新的日子。走运当然是好的，不过我情愿做到分毫不差。这样，运气来的时候，你就有所准备了。",
    "from": "海明威《老人与海》"
  },
  {
    "hitokoto": "不管怎么说，明天又是新的一天。",
    "from": "玛格丽特·米切尔《飘》"
  },
  {
    "hitokoto": "毕竟，明天又是新的一天。",
    "from": "玛格丽特·米切尔《飘》"
  },
  {
    "hitokoto": "对于世界而言，你是一个人；但是对于某个人，你是他的整个世界。",
    "from": "玛格丽特·米切尔《飘》"
  },
  {
    "hitokoto": "直到你失去了，你才知道你曾经拥有什么。",
    "from": "《爱在黎明破晓前》"
  },
  {
    "hitokoto": "我觉得，这就像是在那一瞬间，我们成为了宇宙中两个最真实的人。",
    "from": "《爱在黎明破晓前》"
  },
  {
    "hitokoto": "我步入丛林，因为我希望生活得有意义，我希望活得深刻，汲取生命中所有的精华。",
    "from": "梭罗《瓦尔登湖》"
  },
  {
    "hitokoto": "大多数人都生活在平静的绝望中。",
    "from": "梭罗《瓦尔登湖》"
  },
  {
    "hitokoto": "我愿意深深地扎入生活，吮尽生活的骨髓，过得扎实，简单，把一切不属于生活的内容剔除得干净利落。",
    "from": "梭罗《瓦尔登湖》"
  },
  {
    "hitokoto": "把一切不属于生活的内容剔除得干净利落。",
    "from": "梭罗《瓦尔登湖》"
  },
  {
    "hitokoto": "人只有献身于社会，才能找出那短暂而有风险的生命的意义。",
    "from": "爱因斯坦"
  },
  {
    "hitokoto": "不要努力成为一个成功者，要努力成为一个有价值的人。",
    "from": "爱因斯坦"
  },
  {
    "hitokoto": "逻辑会把你从A带到B，想象力能带你去任何地方。",
    "from": "爱因斯坦"
  },
  {
    "hitokoto": "教育就是当一个人把在学校所学全部忘光之后剩下的东西。",
    "from": "爱因斯坦"
  },
  {
    "hitokoto": "如果我看得比别人更远些，那是因为我站在巨人的肩膀上。",
    "from": "牛顿"
  },
  {
    "hitokoto": "我不知道世人怎样看我，但我自己以为我不过像一个在海边玩耍的孩子，不时为发现比寻常更为美丽的一块卵石或一片贝壳而沾沾自喜，至于展现在我面前的浩翰的真理海洋，却全然没有发现。",
    "from": "牛顿"
  },
  {
    "hitokoto": "生存还是毁灭，这是一个问题。",
    "from": "莎士比亚"
  },
  {
    "hitokoto": "不要温和地走进那个良夜。",
    "from": "狄兰·托马斯"
  },
  {
    "hitokoto": "怒斥，怒斥光明的消逝。",
    "from": "狄兰·托马斯"
  },
  {
    "hitokoto": "如果冬天来了，春天还会远吗？",
    "from": "雪莱《西风颂》"
  },
  {
    "hitokoto": "冬天来了，春天还会远吗？",
    "from": "雪莱"
  },
  {
    "hitokoto": "生如夏花之绚烂，死如秋叶之静美。",
    "from": "泰戈尔《飞鸟集》"
  },
  {
    "hitokoto": "世界以痛吻我，要我报之以歌。",
    "from": "泰戈尔《飞鸟集》"
  },
  {
    "hitokoto": "天空没有留下鸟的痕迹，但我已飞过。",
    "from": "泰戈尔《飞鸟集》"
  },
  {
    "hitokoto": "只有经历过地狱般的磨砺，才能练就创造天堂的力量；只有流过血的手指，才能弹出世间的绝响。",
    "from": "泰戈尔《飞鸟集》"
  },
  {
    "hitokoto": "孤独是一个人的狂欢，狂欢是一群人的孤独。",
    "from": "泰戈尔"
  },
  {
    "hitokoto": "你的负担将变成礼物，你受的苦将照亮你的路。",
    "from": "泰戈尔"
  },
  {
    "hitokoto": "不要着急，最好的总会在最不经意的时候出现。",
    "from": "泰戈尔"
  },
  {
    "hitokoto": "我们看错了世界，却说世界欺骗了我们。",
    "from": "泰戈尔"
  },
  {
    "hitokoto": "即使翅膀折了，心也要飞翔。",
    "from": "泰戈尔"
  },
  {
    "hitokoto": "如果你因失去了太阳而流泪，那么你也将失去群星了。",
    "from": "泰戈尔《飞鸟集》"
  },
  {
    "hitokoto": "你微微地笑着，不同我说什么话。而我觉得，为了这个，我已等待得很久了。",
    "from": "泰戈尔《飞鸟集》"
  },
  {
    "hitokoto": "即使将来无望，也要在绝望中寻找希望。",
    "from": "泰戈尔"
  },
  {
    "hitokoto": "生命的意义在于付出，在于给予，而不是在于接受，也不是在于争取。",
    "from": "巴金"
  },
  {
    "hitokoto": "我之所以写作，不是我有才华，而是我有感情。",
    "from": "巴金"
  },
  {
    "hitokoto": "理想不抛弃苦心追求的人，只要不停止追求，你们会沐浴在理想的光辉之中。",
    "from": "巴金"
  },
  {
    "hitokoto": "真正的勇士，敢于直面惨淡的人生，敢于正视淋漓的鲜血。",
    "from": "鲁迅"
  },
  {
